INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '填空', 1, '{"stem": "63÷3 的商是（　）位数。", "options": null}', '两', '63÷3=21，21 是两位数，所以商是两位数。（十位 6÷3=2，够商 1，商一定是两位数）', 'paper', '["practice", "ykl3sx", "4.4"]', '["paper_png/ykl3_sx/p073.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '填空', 2, '{"stem": "小玲把□÷4 误看作□×4，结果是 96，则□÷4=（　）。", "options": null}', '6', '先求□：□×4=96，□=96÷4=24（80÷4=20，16÷4=4，20+4=24）；再算 24÷4=6。', 'paper', '["practice", "ykl3sx", "4.4"]', '["paper_png/ykl3_sx/p073.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '填空', 2, '{"stem": "□6 是一个两位数，要使 □6÷5 的商也是两位数，□ 里可以填（　）。", "options": null}', '5~9', '两位数除以 5 商要是两位数，被除数必须不小于 5×10=50，所以十位 □ 可取 5、6、7、8、9。', 'paper', '["practice", "ykl3sx", "4.4"]', '["paper_png/ykl3_sx/p073.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
