INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '应用题', 3, '{"stem": "一只老猫捉了 12 只老鼠，其中有一只小白鼠。老猫说：“我要分三批吃它们。吃之前要它们站好队，我从头一个开始吃，隔一个吃掉一个：第一次吃掉站在第 1、3、5、7、9、11 号位置的小老鼠，剩下的不许动；第二次还是从头一个吃起，隔一个吃一个；第三次也照这个方法吃，但把最后剩下的一个放了。”小白鼠听到后站了一个位置，最后没有被吃掉。你知道小白鼠站的是第几号位置吗？", "options": null}', '第8号', '第一次吃掉单数位置，剩下第 2、4、6、8、10、12 号；第二次从头隔一个吃一个，吃掉第 2、6、10 号，剩下第 4、8、12 号；第三次再隔一个吃一个，吃掉第 4、12 号，最后剩下第 8 号。所以小白鼠应站在第 8 号位置。', 'paper', '["practice", "ykl3sx", "4.4"]', '["paper_png/ykl3_sx/p074.png"]', 0);
